/** Daftar seri milik satu brand (UUID). */
export function getBatch2SeriByBrandId(brandId: string): ProdukKomersialBatch2Seri[] {
  return PK_BATCH2_SERI_LIST.filter(s => s.brandId === brandId);
}

/** Lookup satu seri via brandId + seriSlug (routing). */
export function getBatch2SeriBySlug(brandId: string, seriSlug: string): ProdukKomersialBatch2Seri | undefined {
  return PK_BATCH2_SERI_LIST.find(s => s.brandId === brandId && s.slug === seriSlug);
}

/** Lookup seri via UUID. */
export function getBatch2SeriByUUID(uuid: string): ProdukKomersialBatch2Seri | undefined {
  return PK_BATCH2_SERI_LIST.find(s => s.uuid === uuid);
}
